import React, { useState } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import { GrAdd, GrUserManager, GrDocumentText } from 'react-icons/gr';
import './Tabs.css';

const tabs = [
  { title: 'Add Tips', icon: <GrAdd />, component: <Tips /> },
  { title: 'Manage Employees', icon: <GrUserManager />, component: <Employees /> },
  { title: 'View Summary', icon: <GrDocumentText />, component: <Summary /> },
];

function Tabs({ username, onLogout }) {
  const [selectedTab, setSelectedTab] = useState(0);

  function onTabClicked(index) {
    setSelectedTab(index);
  }

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>Dashboard</h1>
        <div className="user-info">
          <FaUserCircle className="user-icon" />
          <span>{username}</span>
          <button className="logout-button" onClick={onLogout}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </header>
      <div className="dashboard-content">
        <nav className="tab-list">
          {tabs.map((tab, index) => (
            <button
              key={index}
              className={`tab-button ${selectedTab === index ? 'active' : ''}`}
              onClick={() => onTabClicked(index)}
            >
              {tab.icon}
              <span>{tab.title}</span>
            </button>
          ))}
        </nav>
        <main className="tab-content">
          {tabs[selectedTab].component}
        </main>
      </div>
    </div>
  );
}

export default Tabs;
